class RateTree:
    def __init__(self, spec: dict):
        self._capacity = {}
        self._rate = {}
        self._parent = {}
        self._tokens = {}
        self._last_update = {}

        for name, (capacity, refill_rate, parent) in spec.items():
            self._capacity[name] = capacity
            self._rate[name] = refill_rate
            self._parent[name] = parent
            self._tokens[name] = capacity  # every bucket starts full
            self._last_update[name] = 0.0

    def _chain(self, name: str):
        chain = []
        node = name
        while node is not None:
            chain.append(node)
            node = self._parent[node]
        return chain

    def _refill(self, node: str, now: float) -> float:
        last = self._last_update[node]
        elapsed = now - last if now > last else 0.0
        new_tokens = min(
            self._capacity[node],
            self._tokens[node] + elapsed * self._rate[node],
        )
        self._tokens[node] = new_tokens
        self._last_update[node] = last if now < last else now
        return new_tokens

    def allow(self, name: str, n: float = 1.0, now: float = 0.0) -> bool:
        chain = self._chain(name)

        available = {node: self._refill(node, now) for node in chain}

        if all(available[node] >= n for node in chain):
            for node in chain:
                self._tokens[node] -= n
            return True

        return False

