        if now > node["last_update"]:
            node["last_update"] = now

    def allow(self, name: str, n: float = 1.0, now: float = 0.0) -> bool:
        chain = self._chain(name)

        for node_name in chain:
            self._refill(node_name, now)

        if all(self.nodes[node_name]["tokens"] >= n for node_name in chain):
            for node_name in chain:
                self.nodes[node_name]["tokens"] -= n
            return True

        return False

class RateTree:
    def __init__(self, spec: dict[str, tuple[float, float, str | None]]):
        self._capacity: dict[str, float] = {}
        self._rate: dict[str, float] = {}
        self._parent: dict[str, str | None] = {}
        self._tokens: dict[str, float] = {}
        self._last_update: dict[str, float] = {}

        for name, (capacity, refill_rate, parent) in spec.items():
            self._capacity[name] = capacity
            self._rate[name] = refill_rate
            self._parent[name] = parent
            self._tokens[name] = capacity  # buckets start FULL
            self._last_update[name] = 0.0

    def _path_to_root(self, name: str) -> list[str]:
        path = []
        cur: str | None = name
        while cur is not None:
            path.append(cur)
            cur = self._parent[cur]
        return path

    def _refill(self, node: str, now: float) -> None:
        last = self._last_update[node]
        if now > last:
            elapsed = now - last
            cap = self._capacity[node]
            self._tokens[node] = min(cap, self._tokens[node] + elapsed * self._rate[node])
            self._last_update[node] = now
        # if now <= last: elapsed treated as zero, no state change (never refill negatively)

    def allow(self, name: str, n: float = 1.0, now: float = 0.0) -> bool:
        path = self._path_to_root(name)

        # Lazily bring every touched node's tokens up to date at `now`.
        for node in path:
            self._refill(node, now)

        if all(self._tokens[node] >= n for node in path):
            for node in path:
                self._tokens[node] -= n
            return True

        return False

