            if mon not in MONTHS:
                return None
            return make_iso(y, MONTHS[mon], d)
        m = re.fullmatch(r'([A-Za-z]{3})\s+(\d{1,2}),\s*(\d{4})', s)
        if m:
            mon = m.group(1)[0].upper() + m.group(1)[1:].lower()
            d = int(m.group(2))
            y = int(m.group(3))
