            return None
        text = re.sub(r'[₹$€]', '', text).strip()
        negative = False
        if text.endswith('DR'):
            prefix = text[:-2].rstrip()
            if prefix:
                negative = True
                text = prefix
        text = text.strip()
        if len(text) >= 2 and text.startswith('(') and text.endswith(')'):
            negative = True
            text = text[1:-1].strip()
        text = text.replace(',', '')
