def max_load(events):
    if not events:
        return (0, 0)

    delta = {}
    for start, end, weight in events:
        delta[start] = delta.get(start, 0) + weight
        delta[end] = delta.get(end, 0) - weight

    running = 0
    peak = 0
    peak_t = 0
    for t in sorted(delta.keys()):
        running += delta[t]
        if running > peak:
            peak = running
            peak_t = t

    return (peak, peak_t)

