def max_load(events):
    if not events:
        return (0, 0)

    deltas = []
    for start, end, weight in events:
        deltas.append((start, weight))
        deltas.append((end, -weight))

    deltas.sort(key=lambda x: x[0])

    peak = 0
    peak_t = 0
    current = 0
    i = 0
    n = len(deltas)
    while i < n:
        t = deltas[i][0]
        j = i
        total_delta = 0
        while j < n and deltas[j][0] == t:
            total_delta += deltas[j][1]
            j += 1
        current += total_delta
        if current > peak:
            peak = current
            peak_t = t
        i = j

    return (peak, peak_t)

